 11	import {
 12	  applyLocality,
 13	  defaultTrustedConfigDeps,
 14	  headOnlyRefusal,
 15	  isLocalVoice,
 16	  isPullRequestContext,
 17	  isSafeRefName,
 18	  loadTrustedConfig,
 19	  localityRefusal,
 20	  providerKeyEnv,
 21	  singleModelLocalityRefusal,
 22	  validateApiKeys,
 23	  yqTrustedView,
 24	  type AgyGate,
 25	  type TrustedConfigDeps,
 26	} from "../config.js";
 27	import { ChevalDelegateAdapter } from "../adapters/cheval-delegate.js";
 28	import { executeMultiModelReview } from "../core/multi-model-pipeline.js";
 29	import type { BridgebuilderConfig, MultiModelConfig, ReviewItem, TrustedConfig } from "../core/types.js";
 30	import type { PRReviewTemplate } from "../core/template.js";
 31	
 32	const GATE: AgyGate = { optIn: false, mode: "prefer-api" };
 33	
 34	const LOCAL_PROVIDER_YAML = [
 35	  "hounfour:",
 36	  "  providers:",
 37	  "    local-vllm:",
 38	  "      type: openai_compat",
 39	  "      endpoint: \"http://127.0.0.1:8000/v1\"",
 40	  "      keyless: true",
 41	  "      allow_insecure_endpoint: \"127.0.0.1\"",
 42	  "      models:",
 43	  "        qwen3-coder:",
 44	  "          dispatch_group: local",
 45	  "          context_window: 32768",
 46	  "",
 47	].join("\n");
 48	
 49	const EMPTY_YAML = "hounfour:\n  providers: {}\n";
 50	
 51	function mm(models: Array<{ provider: string; model_id: string }>): MultiModelConfig {
 52	  return {
 53	    enabled: true,
 54	    models: models.map((m) => ({ ...m, role: "reviewer" as const })),
 55	    api_key_mode: "graceful",
 56	  } as MultiModelConfig;
 57	}
 58	
 59	/** Fake I/O: a working tree (the head, on a PR) and a map of ref -> base config text. */
 60	function fakeDeps(opts: {
 61	  env?: Record<string, string | undefined>;
 62	  head?: string;
 63	  refs?: Record<string, string | undefined>;
 64	  prBase?: string;
 65	}): TrustedConfigDeps & { shown: string[] } {
 66	  const shown: string[] = [];
 67	  return {
 68	    shown,
 69	    env: opts.env ?? {},
 70	    readWorkingTree: () => opts.head,
 71	    refExists: (_root, ref) => Object.hasOwn(opts.refs ?? {}, ref),
 72	    gitShow: (_root, ref) => {
 73	      shown.push(ref);
 74	      return (opts.refs ?? {})[ref];
 75	    },
 76	    prBaseRef: () => opts.prBase,
 77	    parse: yqTrustedView,
 78	  };
 79	}
 80	
 81	describe("trusted provider configuration (D-7.5)", () => {
 82	  it("local mode trusts the working tree: a keyless provider needs no env var", () => {
 83	    const deps = fakeDeps({ head: LOCAL_PROVIDER_YAML });
 84	    const t = loadTrustedConfig({}, deps);
 85	    assert.equal(t.mode, "local");
 86	    assert.equal(t.source, "working-tree");
