 59	/** Fake I/O: a working tree (the head, on a PR) and a map of ref -> base config text. */
 60	function fakeDeps(opts: {
 61	  env?: Record<string, string | undefined>;
 62	  head?: string;
 63	  refs?: Record<string, string | undefined>;
 64	  prBase?: string;
 65	}): TrustedConfigDeps & { shown: string[] } {
 66	  const shown: string[] = [];
