 68	    shown,
 69	    env: opts.env ?? {},
 70	    readWorkingTree: () => opts.head,
 71	    refExists: (_root, ref) => Object.hasOwn(opts.refs ?? {}, ref),
 72	    gitShow: (_root, ref) => {
 73	      shown.push(ref);
 74	      return (opts.refs ?? {})[ref];
 75	    },
 76	    prBaseRef: () => opts.prBase,
